package com.novacommerce.order.infrastructure.client; import com.novacommerce.order.api.error.OrderException; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.*;
@Component public class InventoryClient{private final RestClient client;public InventoryClient(@Qualifier("inventoryRestClient")RestClient c){client=c;}public Reservation reserve(UUID order,List<Item>items,String token){try{return client.post().uri("/api/v1/inventory/reservations").header(HttpHeaders.AUTHORIZATION,"Bearer "+token).header("Idempotency-Key","order-reservation:"+order).contentType(MediaType.APPLICATION_JSON).body(new Request(items)).retrieve().body(Reservation.class);}catch(HttpClientErrorException.Conflict e){throw new OrderException(HttpStatus.CONFLICT,"INVENTORY_UNAVAILABLE","Inventory could not reserve the cart");}catch(RuntimeException e){throw new UnknownInventoryResultException(e);}}public void release(UUID reservation,String token){try{client.post().uri("/api/v1/inventory/reservations/{id}/release",reservation).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().toBodilessEntity();}catch(HttpStatusCodeException e){throw new OrderException(HttpStatus.BAD_GATEWAY,"INVENTORY_RELEASE_REJECTED","Inventory did not accept the release request");}catch(RuntimeException e){throw new UnknownInventoryResultException(e);}}public record Item(UUID variantId,long quantity){}record Request(List<Item>items){}public record Reservation(UUID id,String status,Instant expiresAt,List<Item>items){}public static class UnknownInventoryResultException extends RuntimeException{public UnknownInventoryResultException(Throwable e){super(e);}}}
